import{_ as o,o as t,c as i,ax as r}from"./chunks/framework.D0-oyZN4.js";const p=JSON.parse('{"title":"Troubleshooting","description":"Every documented Developer Studio CLI error message, what it means, and how to recover.","frontmatter":{"description":"Every documented Developer Studio CLI error message, what it means, and how to recover."},"headers":[],"relativePath":"cli/reference/troubleshooting.md","filePath":"cli/reference/troubleshooting.md"}'),d={name:"cli/reference/troubleshooting.md"};function s(a,e,n,c,l,h){return t(),i("div",null,[...e[0]||(e[0]=[r('<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /docs/cli/reference/troubleshooting.md for this page in Markdown format</div><h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>Reference of the error messages <code>gsds</code> prints and the state each one describes.</p><h2 id="directory-path-is-not-empty" tabindex="-1"><code>Directory &quot;&lt;path&gt;&quot; is not empty</code> <a class="header-anchor" href="#directory-path-is-not-empty" aria-label="Permalink to &quot;`Directory &quot;&lt;path&gt;&quot; is not empty`&quot;">​</a></h2><p><code>gsds init</code> didn&#39;t recognize the target directory as an existing widget project — none of <code>extensions_registry.json</code>, <code>connectors_registry.json</code>, <code>gsds.json</code>, or the legacy <code>widget_registry.json</code> are present — and it isn&#39;t empty.</p><p><strong>Recover:</strong> If the directory already has project files that should have matched one of the names above (perhaps under a slightly different name), fix that first. Otherwise, if you&#39;re sure the directory is safe to scaffold into, re-run with <code>--force</code>. See <a href="./commands.html#gsds-init"><code>gsds init</code></a> for the full list of what&#39;s recognized without it.</p><h2 id="no-gsds-json-found" tabindex="-1"><code>no gsds.json found</code> <a class="header-anchor" href="#no-gsds-json-found" aria-label="Permalink to &quot;`no gsds.json found`&quot;">​</a></h2><p><code>gsds</code> is running outside a project. Every command except <code>gsds init</code> requires a <code>gsds.json</code> marker in the current directory or an ancestor.</p><p><strong>Recover:</strong> <code>cd</code> into your project root, or scaffold a new project with <code>gsds init &lt;name&gt;</code>.</p><h2 id="session-is-invalid-or-expired" tabindex="-1"><code>session is invalid or expired</code> <a class="header-anchor" href="#session-is-invalid-or-expired" aria-label="Permalink to &quot;`session is invalid or expired`&quot;">​</a></h2><p>The stored session token failed against your tenant. Session tokens are valid for 8 hours and cannot be refreshed. Affects <code>gsds preview</code> and <code>gsds connector test</code>.</p><p><strong>Recover:</strong> Get a fresh pairing code from <strong>Integrations → Developer Studio → CLI Access</strong> in your community and redeem it with <code>gsds login &lt;pairing_code&gt;</code>. Confirm with <code>gsds login --status</code>.</p><h2 id="pairing-code-expired" tabindex="-1">Pairing code expired <a class="header-anchor" href="#pairing-code-expired" aria-label="Permalink to &quot;Pairing code expired&quot;">​</a></h2><p>Pairing codes have a 1-minute time-to-live.</p><p><strong>Recover:</strong> Get a fresh pairing code from <strong>CLI Access</strong> and redeem it immediately, with your terminal already open.</p><h2 id="missing-required-field-category" tabindex="-1"><code>Missing required field: category</code> <a class="header-anchor" href="#missing-required-field-category" aria-label="Permalink to &quot;`Missing required field: category`&quot;">​</a></h2><p>A <code>widget.json</code> in your project is missing a required field. <code>gsds build</code> refuses to write the registry until every <code>widget.json</code> declares a non-empty <code>title</code> and <code>category</code>.</p><p><strong>Recover:</strong> Add a <code>category</code> string to the <code>widget.json</code> named in the error.</p><h2 id="script-x-points-at-missing-file" tabindex="-1"><code>Script &quot;x&quot; points at missing file</code> <a class="header-anchor" href="#script-x-points-at-missing-file" aria-label="Permalink to &quot;`Script &quot;x&quot; points at missing file`&quot;">​</a></h2><p>A <code>extensions_registry.json</code> entry references a file that no longer exists in the project. <code>gsds build</code> refuses to regenerate the registry while it is inconsistent.</p><p><strong>Recover:</strong> Either restore the missing file, or remove the stale entry with <code>gsds script rm &lt;name&gt;</code> or <code>gsds style rm &lt;name&gt;</code>. <code>gsds create</code> warns on the same drift without failing, so you can scaffold new widgets while cleaning up.</p><h2 id="version-mismatch-across-widgets" tabindex="-1"><code>version mismatch across widgets</code> <a class="header-anchor" href="#version-mismatch-across-widgets" aria-label="Permalink to &quot;`version mismatch across widgets`&quot;">​</a></h2><p>Two widgets declare the same dependency in <code>package.json</code> but resolve it to different installed versions. <code>gsds build</code> externalizes a shared dependency into one import map entry, so it cannot serve two versions at once.</p><p><strong>Recover:</strong> The error names each widget and version. Align the versions, or remove the dependency from one widget, then re-run <code>gsds build</code>. See <a href="./../share-dependencies.html">Share Dependencies Across Widgets</a>.</p><h2 id="excluded-from-shared-dependency-deduplication" tabindex="-1"><code>excluded from shared-dependency deduplication</code> <a class="header-anchor" href="#excluded-from-shared-dependency-deduplication" aria-label="Permalink to &quot;`excluded from shared-dependency deduplication`&quot;">​</a></h2><p>A widget&#39;s <code>vite.config.ts</code> (or <code>angular.json</code>) couldn&#39;t be auto-migrated to the externalized-dependency shape. This only happens once the widget actually shares a dependency with another widget, and its build file has a shape <code>gsds build</code> can&#39;t confidently patch — a custom <code>rollupOptions</code>, or a build block laid out differently than the standard template.</p><p><strong>Recover:</strong> Copy the <code>externalPackages</code> block from a freshly scaffolded widget&#39;s <code>vite.config.ts</code> into the named widget&#39;s file. See <a href="./../share-dependencies.html">Share Dependencies Across Widgets</a>.</p><h2 id="payload-rejected" tabindex="-1"><code>--payload</code> rejected <a class="header-anchor" href="#payload-rejected" aria-label="Permalink to &quot;`--payload` rejected&quot;">​</a></h2><p><code>--payload</code> accepts a file reference only. Inline JSON, and files that do not contain valid JSON, are rejected.</p><p><strong>Recover:</strong> Put the payload in a file and pass it as <code>--payload @body.json</code>. Confirm the file parses as JSON.</p><h2 id="port-in-use" tabindex="-1">Port in use <a class="header-anchor" href="#port-in-use" aria-label="Permalink to &quot;Port in use&quot;">​</a></h2><p><code>gsds preview</code> failed to bind its default port.</p><p><strong>Recover:</strong> <code>gsds preview --port &lt;port&gt;</code> on a free port.</p><h2 id="widget-missing-from-the-picker" tabindex="-1">Widget missing from the picker <a class="header-anchor" href="#widget-missing-from-the-picker" aria-label="Permalink to &quot;Widget missing from the picker&quot;">​</a></h2><p><code>gsds preview</code> is running but a widget does not appear in the No-Code Builder.</p><p><strong>Recover:</strong> Confirm the widget&#39;s <code>package.json</code> declares a <code>dev</code> script. <code>gsds preview</code> boots each widget&#39;s <code>dev</code> script — widgets without one are skipped.</p><h2 id="widget-missing-from-the-registry-after-gsds-build" tabindex="-1">Widget missing from the registry after <code>gsds build</code> <a class="header-anchor" href="#widget-missing-from-the-registry-after-gsds-build" aria-label="Permalink to &quot;Widget missing from the registry after `gsds build`&quot;">​</a></h2><p>Its dependency install failed. <code>gsds build</code> installs each widget&#39;s dependencies automatically and skips a widget whose install fails, without failing the rest of the build.</p><p><strong>Recover:</strong> Run <code>npm install</code> (or your package manager&#39;s equivalent) inside the named widget&#39;s directory to see the underlying install error. Fix it, then re-run <code>gsds build</code>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li>Session model → <a href="./../authenticate.html">Authenticate</a></li><li>Where <code>.gsds/</code> and the keychain fit in → <a href="./project-files.html">Project files</a></li><li>Flags for each command → <a href="./commands.html">Command reference</a></li><li>Shared dependency deduplication → <a href="./../share-dependencies.html">Share Dependencies Across Widgets</a></li></ul>',41)])])}const u=o(d,[["render",s]]);export{p as __pageData,u as default};
